<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { detalleTrabajo,eliminarTrabajo,guardarTrabajo,listarTrabajos,type Options,type Trabajo } from '../services/trabajos'
const rows=ref<Trabajo[]>([]),options=ref<Options>({expedientes:[],tipos_trabajo:[],resultados:[],acciones_flujo:[],estados:[],responsables:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Trabajo|null>(null),editing=ref<number|null>(null)
const filters=reactive({criterio:'',tipotrabajo_id:'',estado_trabajo:'',resultado_id:'',desde:'',hasta:'',page:1}),form=reactive({numero_trabajo:'',expediente_id:'',tipotrabajo_id:'',tiporesultado_id:'',accionflujo_id:'',estado_trabajo:'PENDIENTE',responsable_id:'',fecha_programada:'',observaciones:''})
const actions=computed(()=>options.value.acciones_flujo.filter(x=>!x.tipo_trabajo_id||String(x.tipo_trabajo_id)===String(form.tipotrabajo_id)))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarTrabajos(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:Trabajo){editing.value=item?.id||null;Object.assign(form,{numero_trabajo:item?.numero_trabajo||'',expediente_id:item?.expediente_id||'',tipotrabajo_id:item?.tipotrabajo_id||'',tiporesultado_id:item?.tiporesultado_id||'',accionflujo_id:item?.accionflujo_id||'',estado_trabajo:item?.estado_trabajo||'PENDIENTE',responsable_id:'',fecha_programada:item?.fecha_programada||'',observaciones:item?.observaciones||''});modal.value=true}
async function save(){if(!form.numero_trabajo||!form.expediente_id||!form.tipotrabajo_id||!form.accionflujo_id){error.value='Complete el número, expediente, tipo de trabajo y acción del flujo.';return}saving.value=true;error.value='';try{const r=await guardarTrabajo(editing.value,form);modal.value=false;success.value='Trabajo guardado correctamente.';detail.value=await detalleTrabajo(editing.value||r.id);await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Trabajo){try{detail.value=await detalleTrabajo(item.id)}catch(e){error.value=message(e)}}async function remove(item:Trabajo){if(!confirm(`¿Eliminar el trabajo ${item.numero_trabajo}?`))return;try{await eliminarTrabajo(item.id);success.value='Trabajo eliminado correctamente.';detail.value=null;await load()}catch(e){error.value=message(e)}}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Trabajos</nav><header class="hero"><div class="mark">OT</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Trabajos comerciales</h1><p>Control de trabajos derivados de expedientes y acciones del flujo de atención.</p></div><strong>{{total}} trabajos</strong><button @click="open()">+ Nuevo trabajo</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Número, expediente o cliente" @keyup.enter="load(1)"></label><label>Tipo<select v-model="filters.tipotrabajo_id"><option value="">Todos</option><option v-for="x in options.tipos_trabajo" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado_trabajo"><option value="">Todos</option><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando trabajos…</div><div v-else-if="!rows.length" class="empty">No se encontraron trabajos comerciales.</div>
<section v-else class="table"><header><span>Trabajo</span><span>Expediente / cliente</span><span>Tipo</span><span>Acción de flujo</span><span>Programación</span><span>Responsable</span><span>Estado / resultado</span><span></span></header><article v-for="item in rows" :key="item.id"><b>{{item.numero_trabajo}}</b><div><b>{{item.expediente}}</b><small>{{item.cliente}}</small></div><span>{{item.tipo_trabajo}}</span><span>{{item.accion_flujo}}</span><time>{{item.fecha_programada||'Sin programar'}}</time><span>{{item.responsable||'Sin asignar'}}</span><div><em>{{item.estado_trabajo}}</em><small>{{item.resultado}}</small></div><footer><button @click="show(item)">Ver</button><button v-if="item.puede_editar" @click="open(item)">Editar</button><button v-if="item.puede_editar" class="danger" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{editing?'MODIFICAR':'NUEVO'}} TRABAJO</small><h2>{{editing?'Editar':'Registrar'}} trabajo comercial</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Número de trabajo *<input v-model.trim="form.numero_trabajo" maxlength="100"></label><label>Expediente *<select v-model="form.expediente_id"><option value="">Seleccione</option><option v-for="x in options.expedientes" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de trabajo *<select v-model="form.tipotrabajo_id" @change="form.accionflujo_id=''" ><option value="">Seleccione</option><option v-for="x in options.tipos_trabajo" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Acción del flujo *<select v-model="form.accionflujo_id"><option value="">Seleccione</option><option v-for="x in actions" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Responsable<select v-model="form.responsable_id"><option value="">Sin asignar</option><option v-for="x in options.responsables" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fecha programada<input v-model="form.fecha_programada" type="datetime-local"></label><label>Estado<select v-model="form.estado_trabajo"><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Resultado<select v-model="form.tiporesultado_id"><option value="">Pendiente</option><option v-for="x in options.resultados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><label>Observaciones<textarea v-model.trim="form.observaciones" rows="4"></textarea></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar trabajo'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>FICHA DEL TRABAJO</small><h2>{{detail.numero_trabajo}}</h2><p>{{detail.expediente}} · {{detail.cliente}}</p></div><button @click="detail=null">×</button></header><div class="summary"><div><b>{{detail.tipo_trabajo}}</b><span>Tipo</span></div><div><b>{{detail.estado_trabajo}}</b><span>Estado</span></div><div><b>{{detail.responsable||'Sin asignar'}}</b><span>Responsable</span></div><div><b>{{detail.resultado||'Pendiente'}}</b><span>Resultado</span></div></div><p class="address">{{detail.direccion||'Sin dirección asociada'}}<br>{{detail.observaciones}}</p><h3>Trazabilidad</h3><div class="history"><p v-if="!detail.historial?.length">Sin movimientos registrados.</p><article v-for="x in detail.historial" :key="x.id"><b>{{x.estado}} <small>{{x.accion}}</small></b><span>{{x.usuario}} · {{x.fecha}}</span><p>{{x.observacion}}</p></article></div><footer><button class="clear" @click="detail=null">Cerrar</button><button v-if="detail.puede_editar" @click="open(detail);detail=null">Editar</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#21a06b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:7px;border-radius:9px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.59rem}.table{margin-top:13px;border-radius:9px;background:#fff;overflow:hidden}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:90px 1.2fr 1fr 1fr 100px 1fr 100px 100px;align-items:center;gap:7px}.table>header{color:#fff;background:var(--accent);font-size:.49rem;font-weight:700}.table>article{border-bottom:1px solid #edf0f2;font-size:.52rem}.table small{display:block;color:#7d898f}.table em{padding:4px;border-radius:9px;background:#eff9f4;font-style:normal}.table footer button{border:0;color:var(--accent);background:none;font-size:.48rem}.table footer .danger{color:#a13f43}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,820px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#eff9f4}.summary b,.summary span{display:block;font-size:.53rem}.address{padding:11px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.56rem}.modal h3{font-size:.65rem}.history article{padding:8px;border-bottom:1px solid #edf0f2;font-size:.54rem}.history article b,.history article span{display:block}.history article span,.history article p{color:#7d898f}.detail{width:min(100%,900px)}@media(max-width:950px){.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.table>article,.grid,.summary{grid-template-columns:1fr}}
</style>
